import pandas as pd


def revenue_per_store(df):
    out = df.assign(revenue=df["quantity"] * df["unit_price"])
    out = out.groupby("store", as_index=False)["revenue"].sum()
    return out.sort_values("revenue", ascending=False).reset_index(drop=True)

