import pandas as pd


def inactive_customers(customers, orders):
    active = orders.loc[orders["status"] != "cancelled", "customer_id"].unique()
    out = customers.loc[~customers["customer_id"].isin(active), ["customer_id", "name"]]
    return out.sort_values("customer_id").reset_index(drop=True)

